/* CS Quest: every word of this game in one language. */
(window.CsqPacks = window.CsqPacks || {})["robo-route"] = Object.assign(window.CsqPacks["robo-route"] || {}, { "ar": {"strings":{"1":"1","2":"2","4":"4","5":"5","6":"6","8":"8","9":"9","10":"10","Two on one device":"اثنان على جهاز واحد","Pair mode on: take turns driving.":"وضع الثنائي مفعّل: تبادلا القيادة.","Pair mode off":"وضع الثنائي متوقّف","Snap blocks together and drive Bolt the robot to the goal!":"ركّب اللبنات معًا وقُد الروبوت بولت إلى الهدف!","Pick a chapter":"اختر فصلًا","Grade band":"الفئة","{band} band":"فئة {band}","Quest Card":"بطاقة المغامرة","Daily Crew Challenge":"تحدّي الطاقم اليومي","{n} stars":{"zero":"{n} نجوم","one":"{n} نجمة","two":"{n} نجمتان","few":"{n} نجوم","many":"{n} نجمة","other":"{n} نجمة"},"One new board today":"لوحة جديدة واحدة اليوم","{n} Explorer stars":{"zero":"{n} نجوم مستكشف","one":"{n} نجمة مستكشف","two":"{n} نجمتا مستكشف","few":"{n} نجوم مستكشف","many":"{n} نجمة مستكشف","other":"{n} نجمة مستكشف"},"{done}/{total} tasks":"{done}/{total} من المهام","{done}/{total} levels":"{done}/{total} من المستويات","Crown":"تاج","Quest code":"رمز المهمة","Type the four digits from your teacher":"اكتب الأرقام الأربعة التي أعطاك إياها معلّمك","A friend tests your level":"صديق يختبر مستواك","{chapter} · Level {n}":"{chapter} · المستوى {n}","Class quest: {chapter} · {band}":"مغامرة الصف: {chapter} · {band}","Swap! The navigator drives now.":"تبديل! الملّاح يقود الآن.","Driver":"السائق","Navigator":"الملّاح","Pair mode: player {n} drives":"وضع الثنائي: اللاعب {n} يقود","Test {n}":"الاختبار {n}","passed":"نجح","failed":"فشل","Blocks: {n} · goal {max} or fewer":"اللبنات: {n} · الهدف {max} أو أقل","Edits: {n}":"التعديلات: {n}","{n} edits from the starter program":{"zero":"{n} تعديلات على البرنامج الأصلي","one":"{n} تعديل على البرنامج الأصلي","two":"{n} تعديلان على البرنامج الأصلي","few":"{n} تعديلات على البرنامج الأصلي","many":"{n} تعديلًا على البرنامج الأصلي","other":"{n} تعديل على البرنامج الأصلي"},"The board: {w} by {h} squares":"اللوحة: {w} في {h} مربّعات","Door: {rule}":"الباب: {rule}","{name} is {value}":"{name} يساوي {value}","Blocks":"اللبنات","Put the plan lines in order first.":"رتّب سطور الخطة أولًا.","Pick a route first: run both and choose one.":"اختر مسارًا أولًا: شغّل كليهما واختر واحدًا.","A when block goes at the top of the program.":"لبنة عندما توضع في أعلى البرنامج.","A My Block goes at the top of the program.":"لبنتي توضع في أعلى البرنامج.","Added {block}":"تمت إضافة {block}","{a} {op} {b}":"{a} {op} {b}","not {x}":"ليس {x}","repeat until {x}":"كرّر حتى {x}","repeat {n} times":{"zero":"كرّر {n} مرات","one":"كرّر {n} مرة","two":"كرّر {n} مرتين","few":"كرّر {n} مرات","many":"كرّر {n} مرة","other":"كرّر {n} مرة"},"if {c}":"إذا {c}","when {e}":"عندما {e}","set {v} to {x}":"اضبط {v} على {x}","change {v} by {n}":"غيّر {v} بمقدار {n}","My Block {name}":"لبنتي {name}","call {name}":"استدعِ {name}","Tap a block on the shelf to start your program.":"انقر لبنة على الرفّ لتبدأ برنامجك.","start here":"ابدأ هنا","Undo":"تراجع","Start over":"ابدأ من جديد","Clear program":"امسح البرنامج","Put the next block here":"ضع اللبنة التالية هنا","inside":"بالداخل","else":"وإلا","end":"النهاية","Route {x}":"المسار {x}","{n} blocks":{"zero":"{n} لبنات","one":"{n} لبنة","two":"{n} لبنتان","few":"{n} لبنات","many":"{n} لبنة","other":"{n} لبنة"},"Run {x}":"شغّل {x}","Use {x}":"استخدم {x}","Route {x} is in the program. Make it better, then run it.":"المسار {x} في البرنامج الآن. حسّنه، ثم شغّله.","Move up":"انقل لأعلى","Move down":"انقل لأسفل","Delete block":"احذف اللبنة","Change":"تغيير","Note chip":"بطاقة ملاحظة","Credit line":"سطر المصدر","Move into the block above":"أدخِل في اللبنة أعلاه","Move into the else part":"انقل إلى جزء وإلا","Wrap the blocks below":"ضمّ اللبنات التي تحتها","Move out of its block":"أخرِج من لبنتها","Add else":"أضف وإلا","Add after this block":"أضف بعد هذه اللبنة","Done":"تم","Less":"أقل","More":"أكثر","How many times?":"كم مرة؟","Use {p}":"استخدم {p}","a box":"صندوق","Takes a number: {p}":"تأخذ عددًا: {p}","First question":"السؤال الأول","Second question":"السؤال الثاني","on":"مشغّل","off":"مطفأ","not":"ليس","What does {name} do?":"ماذا تفعل {name}؟","Stop":"أوقف","Run":"شغّل","Make a block, then call it. Run wakes up when the program calls a block.":"اصنع لبنة، ثم استدعِها. يستيقظ زر شغّل عندما يستدعي البرنامج لبنة.","Routes":"المسارات","Step":"خطوة","Reset":"إعادة","Hint":"تلميح","Learn":"تعلّم","Back to the maker":"العودة إلى الصانع","Skip level":"تخطَّ المستوى","Chapter map":"خريطة الفصل","Hints open after two tries at Pro: one more run.":"في مستوى المحترف تُفتح التلميحات بعد محاولتين: تشغيل واحد آخر.","Run your program first. Hints open after two tries at Pro.":"شغّل برنامجك أولًا. في مستوى المحترف تُفتح التلميحات بعد محاولتين.","Run your program first. Hints open after a try.":"شغّل برنامجك أولًا. تُفتح التلميحات بعد محاولة.","Not yet.":"ليس بعد.","The program is empty. Tap a block on the shelf.":"البرنامج فارغ. انقر لبنة على الرفّ.","Board {n} of {total}":"اللوحة {n} من {total}","Route {x} works: {n} blocks.":{"zero":"المسار {x} يعمل: {n} لبنات.","one":"المسار {x} يعمل: {n} لبنة.","two":"المسار {x} يعمل: {n} لبنتان.","few":"المسار {x} يعمل: {n} لبنات.","many":"المسار {x} يعمل: {n} لبنة.","other":"المسار {x} يعمل: {n} لبنة."},"Route {x} fails. {why}":"المسار {x} يفشل. {why}","Bump! A wall after step {n}.":"بوم! جدار بعد الخطوة {n}.","Splash!":"سبلاش!","Nothing to pick up here.":"لا شيء لالتقاطه هنا.","Hints are open now.":"التلميحات مفتوحة الآن.","Tested! Your friend solved it.":"تم الاختبار! صديقك حلّه.","Bolt made it!":"بولت وصل!","Level tested!":"تم اختبار المستوى!","Daily Crew Challenge done!":"أنجزت تحدّي الطاقم اليومي!","Fix it in {n} edits or fewer for the next star.":"أصلحه بعدد تعديلات لا يزيد على {n} لتنال النجمة التالية.","Use {n} blocks or fewer for the next star.":"استخدم {n} لبنات أو أقل لتنال النجمة التالية.","Solve it without the third hint for the next star.":"حُلّه دون التلميح الثالث لتنال النجمة التالية.","Chapter: {n} stars":"نجوم الفصل: {n}","Level {n} done!":"أنجزت المستوى {n}!","Level skipped":"تم تخطّي المستوى","Quest complete!":"اكتملت المغامرة!","{chapter} complete!":"اكتمل فصل {chapter}!","Great work. Tell your teacher you finished, or play the chapter again for more stars.":"عمل رائع. أخبر معلّمك أنك أنهيته، أو العب الفصل مرة أخرى لتجمع مزيدًا من النجوم.","{n} of {all} stars":"{n} من {all} نجوم","{ok} of {n} checks right":"{ok} من {n} إجابات صحيحة","Back to class":"العودة إلى الصف","All done. Your teacher can see your stars now.":"انتهيت. يستطيع معلّمك رؤية نجومك الآن.","Play again":"العب مرة أخرى","Let's go!":"هيا بنا!","Build the flowchart":"ابنِ المخطط الانسيابي","Plan first":"خطّط أولًا","Tap the shapes in the order the chart runs them: boxes are actions, diamonds are questions. Then the shelf opens, and your blocks must follow the chart.":"انقر الأشكال بالترتيب الذي ينفّذها به المخطط: المستطيلات أفعال، والمعيّنات أسئلة. بعدها يُفتح الرفّ، ويجب أن تتبع لبناتك المخطط.","Tap the plan lines in the order Bolt should do them. Then the shelf opens.":"انقر سطور الخطة بالترتيب الذي يجب أن ينفّذها به بولت. بعدها يُفتح الرفّ.","The shelf is open.":"الرفّ مفتوح.","Hint {n} of 3":"التلميح {n} من 3","This hint shows a move, so the third star stays in the box this time.":"هذا التلميح يكشف خطوة، لذا تبقى النجمة الثالثة في الصندوق هذه المرة.","Got it":"فهمت","Route check":"فحص المسار","How sure were you?":"كم كنت متأكدًا؟","Not yet":"ليس بعد","Getting it":"بدأت أفهم","Got it!":"فهمتها!","Read aloud":"اقرأ بصوت عالٍ","Sound and more":"الصوت والمزيد","Keyboard: 1 to 8 add a block, Delete removes it, R or Ctrl+Enter runs.":"لوحة المفاتيح: من 1 إلى 8 لإضافة لبنة، وDelete للحذف، وR أو Ctrl+Enter للتشغيل.","Enter a quest code":"أدخل رمز المغامرة","Delete":"حذف","Go":"انطلق","Four digits, please.":"أربعة أرقام من فضلك.","Close":"إغلاق","No chapter has that number yet.":"لا يوجد فصل بهذا الرقم بعد.","No band has that number.":"لا توجد فئة بهذا الرقم.","Task {n} of {total}":"المهمة {n} من {total}","Your own level":"مستواك الخاص","Paint a board, press Check, then hand the device to a friend to test it.":"ارسم لوحة، اضغط تحقّق، ثم أعطِ الجهاز لصديق ليختبرها.","goal":"الهدف","gem":"جوهرة","key":"مفتاح","Bolt":"بولت","Square {x}, {y}: {what}":"المربّع {x}، {y}: {what}","Tiles":"المربعات","{tile} tile":"بلاطة {tile}","Check":"تحقّق","Test with a friend":"اختبره مع صديق","Level code":"رمز المستوى","Skip task":"تخطَّ المهمة","Task skipped":"تم تخطي المهمة","What did your tester say?":"ماذا قال من جرّب مستواك؟","One fun thing:":"شيء ممتع:","The route":"المسار","The gems":"الجواهر","The tricky corner":"الزاوية الصعبة","The door":"الباب","One confusing thing:":"شيء محيّر:","Too easy":"سهل جدًا","Too hard":"صعب جدًا","A dead end":"طريق مسدود","Nothing":"لا شيء","Change one thing, then press Check again":"غيّر شيئًا واحدًا، ثم اضغط تحقّق مرة أخرى","Not now":"ليس الآن","Save level":"احفظ المستوى","My levels":"مستوياتي","Enter a code":"أدخل رمزًا","Clear board":"امسح اللوحة","Next task":"المهمة التالية","The tasks":"المهام","based on {code}":"مبني على {code}","Improved after a test":"تحسّن بعد التجربة","Four gems at most.":"أربع جواهر على الأكثر.","Level fixed!":"تم إصلاح المستوى!","Task {n} done!":"أنجزت المهمة {n}!","Now make your own!":"والآن اصنع مستواك الخاص!","Plan it on paper, paint it, press Check, then hand the device to a friend to test it.":"خطّطه على الورق، ارسمه، اضغط تحقّق، ثم أعطِ الجهاز لصديق ليختبره.","Press Check first: a level must be solvable before a friend tests it.":"اضغط تحقّق أولًا: يجب أن يكون المستوى قابلًا للحل قبل أن يختبره صديق.","Hand the device to your tester. Stay quiet and watch: say nothing until they are done.":"أعطِ الجهاز لمن سيختبره. ابقَ صامتًا وراقب: لا تقل شيئًا حتى ينتهي.","Ready":"جاهز","Read it out or write it on the board: a friend types it in with Enter a code on their device.":"اقرأه بصوت عالٍ أو اكتبه على السبورة: يكتبه صديقك عبر «أدخل رمزًا» على جهازه.","Place Bolt and the goal first. Then the board gets a code.":"ضع بولت والهدف أولًا. بعدها تحصل اللوحة على رمز.","Open level":"افتح المستوى","That code does not open a level. Check every symbol.":"هذا الرمز لا يفتح أي مستوى. تحقّق من كل رمز فيه.","A remix: change the board, keep the based-on stamp, press Check.":"ريمكس: غيّر اللوحة، أبقِ ختم «مبني على»، اضغط تحقّق.","Level opened.":"تم فتح المستوى.","Saved. {n} levels in your box.":{"zero":"تم الحفظ. {n} مستويات في صندوقك.","one":"تم الحفظ. {n} مستوى في صندوقك.","two":"تم الحفظ. {n} مستويان في صندوقك.","few":"تم الحفظ. {n} مستويات في صندوقك.","many":"تم الحفظ. {n} مستوى في صندوقك.","other":"تم الحفظ. {n} مستوى في صندوقك."},"No saved levels yet. Press Save level in the maker.":"لا توجد مستويات محفوظة بعد. اضغط احفظ المستوى في الصانع.","Sequences":"التسلسل","Loops":"حلقات التكرار","Conditionals & events":"الشروط والأحداث","Variables":"المتغيّرات","Functions":"الدوال","Debug Lab":"مختبر التصحيح","Best Route":"أفضل مسار","Level Maker":"صانع المستويات","move":"تحرّك","turn left":"استدر يسارًا","turn right":"استدر يمينًا","pick up":"التقط","drop":"أسقط","repeat":"كرّر","repeat until goal":"كرّر حتى الهدف","repeat until wall ahead":"كرّر حتى جدار أمامي","if":"إذا","if / else":"إذا / وإلا","when":"عندما","set":"اضبط","change by":"غيّر بمقدار","My Block":"لبنتي","call":"استدعِ","floor":"أرضية","wall":"جدار","water":"ماء","door":"باب","path ahead":"الطريق مفتوح","wall ahead":"جدار أمامي","on a gem":"على جوهرة","something to pick up":"شيء لالتقاطه","on paint":"على طلاء","I have the key":"معي المفتاح","on the button":"على الزر","on the goal":"على الهدف","a gem is picked up":"تُلتقط جوهرة","Bolt bumps":"يصطدم بولت","the button is pressed":"يُضغط الزر","Picks up the gems":"يلتقط الجواهر","Drives down the side":"يقود نزولًا على الجانب","Drives to the goal":"يقود إلى الهدف","Spins around on the spot":"يدور في مكانه","Climbs a zigzag staircase":"يصعد سلّمًا متعرّجًا","Drives straight up":"يقود مباشرة لأعلى","based on Starter blocks":"مبني على اللبنات الجاهزة","by the Robo Route team":"من فريق روبو روت","Place Bolt first.":"ضع بولت أولًا.","Place the goal flag.":"ضع علم الهدف.","A door needs a key, or gems to count.":"الباب يحتاج إلى مفتاح، أو جواهر لعدّها.","No way to the goal. Open a path, or put the key before the door.":"لا طريق إلى الهدف. افتح ممرًّا، أو ضع المفتاح قبل الباب.","Solvable, but par is only {n}. Make it harder.":"قابل للحل، لكن الحد الأدنى {n} فقط. اجعله أصعب.","Add a gem.":"أضف جوهرة.","Add a key.":"أضف مفتاحًا.","Add a door.":"أضف بابًا.","Change at least {n} squares.":{"zero":"غيّر {n} مربّعات على الأقل.","one":"غيّر {n} مربّعًا على الأقل.","two":"غيّر {n} مربّعين على الأقل.","few":"غيّر {n} مربّعات على الأقل.","many":"غيّر {n} مربّعًا على الأقل.","other":"غيّر {n} مربّع على الأقل."},"Solvable! Par {n}.":"قابل للحل! الحد الأدنى {n}.","What should a player have to figure out on your board?":"ما الذي يجب أن يكتشفه اللاعب في لوحتك؟","Place Bolt and the goal first, then press Check. Walls and water make the route; gems and a key make a quest.":"ضع بولت والهدف أولًا، ثم اضغط تحقّق. الجدران والماء تصنع المسار؛ والجواهر والمفتاح تصنع مغامرة.","A good first level: one corner, one gem, a par of six or more.":"مستوى أول جيد: زاوية واحدة، جوهرة واحدة، وحد أدنى ستة أو أكثر.","Count the squares, or let a loop count them.":"عُدّ المربّعات، أو دع حلقة تعدّها.","A corner needs a turn. A gem needs a pick up where Bolt stands.":"الزاوية تحتاج إلى استدارة. والجوهرة تحتاج إلى التقاط حيث يقف بولت.","Drive to the first turn, turn, then drive again.":"قُد إلى الاستدارة الأولى، استدر، ثم قُد مرة أخرى.","What changes from day to day on this board? Bolt has to notice it as it drives.":"ما الذي يتغيّر من يوم إلى يوم في هذه اللوحة؟ يجب أن يلاحظه بولت وهو يقود.","Build the loop first, then put the if or when inside it.":"ابنِ الحلقة أولًا، ثم ضع إذا أو عندما بداخلها.","The corner is somewhere along the way. Let Bolt feel for it with an if.":"الزاوية في مكان ما على الطريق. دع بولت يتحسّسها بلبنة إذا.","Paint marks the corners. Move, then ask: on paint?":"الطلاء يحدّد الزوايا. تحرّك، ثم اسأل: على طلاء؟","A bump can be useful: catch it with a when block and turn.":"الاصطدام قد يكون مفيدًا: التقطه بلبنة عندما واستدر.","Pick up only when there is a gem under Bolt.":"التقط فقط عندما تكون هناك جوهرة تحت بولت.","One rule for every wall: if the path is clear move, else turn.":"قاعدة واحدة لكل جدار: إذا كان الطريق مفتوحًا تحرّك، وإلا استدر.","The door wants the true number of gems in the count box.":"الباب يريد العدد الحقيقي للجواهر في صندوق count.","Two questions every step: a gem here? a path ahead?":"سؤالان في كل خطوة: هل هنا جوهرة؟ هل الطريق أمامي مفتوح؟","red":"أحمر","blue":"أزرق","green":"أخضر","yellow":"أصفر","a repeat block":"لبنة كرّر","a repeat inside a repeat":"كرّر داخل كرّر","an if block":"لبنة إذا","a when block":"لبنة عندما","a call block":"لبنة استدعِ","a My Block":"لبنتي","a set block":"لبنة اضبط","a change block":"لبنة غيّر","and":"و","or":"أو","Explorer":"مستكشف","Pro":"محترف","An algorithm is a list of steps in order":"الخوارزمية هي قائمة خطوات مرتّبة","Bolt does exactly what the blocks say, one after another, from the top. Tap a block on the shelf to add it to the program, then press Run.":"ينفّذ بولت ما تقوله اللبنات بالضبط، واحدة تلو الأخرى، من الأعلى. انقر لبنة على الرفّ لتضيفها إلى البرنامج، ثم اضغط شغّل.","How many squares does Bolt move to reach the flag?":"كم مربعًا يتحرّك بولت ليصل إلى العلم؟","The numbers on the floor count the squares. The flag square counts too.":"الأرقام على الأرض تعدّ المربعات. مربع العلم يُحسب أيضًا.","Use one move block for each square, up to and including the flag square.":"استخدم لبنة تحرّك واحدة لكل مربع، حتى مربع العلم ومعه.","Bolt runs the blocks...":"ينفّذ بولت اللبنات...","in order, from the top":"بالترتيب، من الأعلى","all at the same time":"كلها في الوقت نفسه","in any order it likes":"بأي ترتيب يعجبه","Count the squares from Bolt to the flag. The flag square counts too.":"عُدّ المربعات من بولت إلى العلم. مربع العلم يُحسب أيضًا.","Does a turn block move Bolt forward?":"هل تحرّك لبنة الاستدارة بولت إلى الأمام؟","A turn spins Bolt on the spot. After the turn, Bolt still needs move blocks.":"الاستدارة تدير بولت في مكانه. بعد الاستدارة، ما زال بولت يحتاج إلى لبنات تحرّك.","Start with the moves that reach the turn, then one turn left block.":"ابدأ بالحركات التي توصل إلى المنعطف، ثم لبنة استدر يسارًا واحدة.","What does turn left do?":"ماذا تفعل لبنة استدر يسارًا؟","Bolt spins to face left and stays on its square":"يدور بولت ليواجه اليسار ويبقى في مربّعه","Bolt moves one square to the left":"يتحرّك بولت مربّعًا واحدًا إلى اليسار","Bolt goes back to the start":"يعود بولت إلى البداية","Stand on the gem, then pick it up. Bolt only picks up what is under it.":"قف على الجوهرة، ثم التقطها. بولت يلتقط فقط ما هو تحته.","Drive onto the gem first and add a pick up there. The turn comes later.":"اذهب إلى الجوهرة أولًا وضع التقط هناك. الاستدارة تأتي لاحقًا.","Where does Bolt have to be when it picks up the gem?":"أين يجب أن يكون بولت عندما يلتقط الجوهرة؟","Pick up works only on the square Bolt is standing on.":"الالتقاط يعمل فقط على المربّع الذي يقف عليه بولت.","The first leg is two moves, then pick up. Build that, then think about the turn.":"الجزء الأول حركتان ثم التقط. ابنِ ذلك، ثم فكّر في الاستدارة.","When does pick up work?":"متى يعمل الالتقاط؟","When Bolt stands on the gem":"عندما يقف بولت على الجوهرة","When Bolt is next to the gem":"عندما يكون بولت بجانب الجوهرة","Any time":"في أي وقت","Plan first, then program":"خطّط أولًا، ثم برمج","Pro programmers write the plan in plain words before they touch the blocks: this is called pseudocode. Put the plan lines in order and the shelf opens.":"المبرمجون المحترفون يكتبون الخطة بكلمات بسيطة قبل أن يلمسوا اللبنات: وهذا ما يُسمّى الشفرة الزائفة. رتّب سطور الخطة فيُفتح الرفّ.","Which plan line comes first?":"أي سطر في الخطة يأتي أولًا؟","Each plan line becomes a run of blocks. Finish one line before you start the next.":"كل سطر في الخطة يصبح سلسلة من اللبنات. أنهِ سطرًا قبل أن تبدأ التالي.","Line 1 is four moves and a pick up. Build that leg first, then run it.":"السطر 1 أربع حركات والتقط. ابنِ هذا الجزء أولًا، ثم شغّله.","Pseudocode is...":"الشفرة الزائفة هي...","the plan in plain words":"الخطة بكلمات بسيطة","a secret robot language":"لغة روبوتات سرّية","the fastest route":"أسرع مسار","Drive to the first gem and pick it up":"قُد إلى الجوهرة الأولى والتقطها","Turn and drive up to the second gem":"استدر وقُد لأعلى إلى الجوهرة الثانية","Turn toward the goal and drive there":"استدر نحو الهدف وقُد إليه","Which squares are water? Bolt cannot swim.":"أي المربّعات ماء؟ بولت لا يستطيع السباحة.","Only one square leads into the flag without a splash: the one below it.":"مربّع واحد فقط يؤدّي إلى العلم دون سقوط في الماء: المربّع الذي تحته.","Drive two squares first, then turn left to face the gap.":"تحرّك مربعين أولًا، ثم استدر يسارًا لتواجه الفتحة.","A program is a set of...":"البرنامج هو مجموعة من...","exact steps for the computer":"خطوات دقيقة للحاسوب","ideas the computer guesses from":"أفكار يخمّن منها الحاسوب","pictures":"صور","How many squares is each leg of the plan?":"كم مربّعًا في كل جزء من الخطة؟","Count each straight run before you add its moves. Water is a splash.":"عُدّ كل مقطع مستقيم قبل أن تضيف حركاته. الماء يعني السقوط.","The first leg is five moves. Then one turn right.":"الجزء الأول خمس حركات. ثم استدارة واحدة يمينًا.","Why write the plan first?":"لماذا نكتب الخطة أولًا؟","It splits a long job into parts you can check":"لأنها تقسّم العمل الطويل إلى أجزاء يمكنك التحقّق منها","It makes Bolt faster":"لأنها تجعل بولت أسرع","Bolt reads the plan":"لأن بولت يقرأ الخطة","Drive east along the top":"قُد شرقًا على طول الصف العلوي","Go down and pick up the gem":"انزل والتقط الجوهرة","Drive back west":"ارجع نحو الغرب","Go down to the goal":"انزل إلى الهدف","There are two ways to the flag. Which one has fewer steps?":"هناك طريقان إلى العلم. أيهما خطواته أقل؟","Going down the left side first is shorter than going along the top.":"النزول من الجانب الأيسر أولًا أقصر من السير على طول الصف العلوي.","Start with turn right: the shorter route goes down the left side first.":"ابدأ بـ استدر يمينًا: المسار الأقصر ينزل من الجانب الأيسر أولًا.","Two programs both reach the flag. Which is better?":"برنامجان كلاهما يصل إلى العلم. أيهما أفضل؟","The one with fewer steps that still works":"الذي خطواته أقل وما زال يعمل","The one with more blocks":"الذي لبناته أكثر","They are always the same":"هما دائمًا متساويان","Count the steps of both routes before you choose.":"عُدّ خطوات المسارين قبل أن تختار.","The route along the top needs four turns; the route down the left needs one.":"المسار على طول الصف العلوي يحتاج إلى أربع استدارات؛ والمسار النازل من اليسار يحتاج إلى واحدة.","Start with turn right: the route down the left side is the shorter one.":"ابدأ بـ استدر يمينًا: المسار من الجانب الأيسر هو الأقصر.","Compare the two routes":"قارن بين المسارين","Pick the shorter one":"اختر الأقصر","Program it":"برمجه","This route has three legs. What is the first leg?":"هذا المسار من ثلاثة أجزاء. ما الجزء الأول؟","Leg 1: along the top to the corner. Leg 2: down. Leg 3: back along the middle to the flag.":"الجزء 1: على طول الصف العلوي حتى الزاوية. الجزء 2: نزول. الجزء 3: عودة عبر الوسط إلى العلم.","Leg 1 is three moves to the gem, then pick up.":"الجزء 1 ثلاث حركات إلى الجوهرة، ثم التقط.","Splitting a long route into legs helps because...":"تقسيم المسار الطويل إلى أجزاء مفيد لأنه...","you can check each small part":"يتيح لك التحقّق من كل جزء صغير","Bolt moves faster":"يجعل بولت يتحرّك أسرع","it uses fewer gems":"يستخدم جواهر أقل","Name the three legs before you build.":"سمِّ الأجزاء الثلاثة قبل أن تبني.","Each leg ends with a turn. Count the squares of each leg.":"كل جزء ينتهي باستدارة. عُدّ مربّعات كل جزء.","Leg 1 is four moves to the gem, then pick up.":"الجزء 1 أربع حركات إلى الجوهرة، ثم التقط.","Leg 1: east along the top, pick up the gem":"الجزء 1: شرقًا على طول الصف العلوي، والتقط الجوهرة","Leg 2: turn and go down":"الجزء 2: استدر وانزل","Leg 3: turn and go west to the goal, picking up the gem":"الجزء 3: استدر واذهب غربًا إلى الهدف، والتقط الجوهرة في الطريق","A loop repeats steps":"الحلقة تكرّر الخطوات","Writing move five times is boring. A repeat block runs the blocks inside it again and again. The number says how many times.":"كتابة تحرّك خمس مرات أمر ممل. لبنة كرّر تشغّل اللبنات التي بداخلها مرة بعد مرة. والعدد يحدّد كم مرة.","How many times does the move block need to run?":"كم مرة يجب أن تعمل لبنة تحرّك؟","Put one move block inside the repeat and set its number to the number of squares.":"ضع لبنة تحرّك واحدة داخل كرّر واضبط عددها على عدد المربّعات.","Tap repeat first, then move: the move lands inside the repeat.":"اضغط كرّر أولًا ثم تحرّك: تدخل الحركة داخل كرّر.","The number on a repeat block means...":"العدد على لبنة كرّر يعني...","how many times the blocks inside run":"كم مرة تعمل اللبنات التي بداخلها","how many squares Bolt moves in one step":"كم مربّعًا يتحرّك بولت في خطوة واحدة","how many blocks you may use":"كم لبنة يمكنك استخدامها","Which steps happen again and again on these stairs?":"أي الخطوات تتكرّر مرة بعد مرة على هذه الدرجات؟","One stair is: move, turn right, move, turn left. The staircase is that stair three times.":"الدرجة الواحدة هي: تحرّك، استدر يمينًا، تحرّك، استدر يسارًا. والسلّم هو تلك الدرجة ثلاث مرات.","Put one stair inside a repeat and count the stairs for its number.":"ضع درجة واحدة داخل كرّر، وعُدّ الدرجات لتعرف رقمها.","What goes inside a repeat block?":"ماذا يوضع داخل لبنة كرّر؟","The steps that happen again and again":"الخطوات التي تتكرّر مرة بعد مرة","Only one move block":"لبنة تحرّك واحدة فقط","The goal":"الهدف","Bolt goes round three sides of a square. What repeats?":"يدور بولت حول ثلاثة أضلاع من مربّع. ما الذي يتكرّر؟","Each side is three moves and a turn right.":"كل ضلع هو ثلاث حركات واستدارة يمينًا.","Put one side inside the repeat: the moves along it, then the turn.":"ضع ضلعًا واحدًا داخل كرّر: الحركات على طوله، ثم الاستدارة.","Look at the gems. Is there a pattern?":"انظر إلى الجواهر. هل هناك نمط؟","Every gem is two squares apart: move, move, pick.":"المسافة بين كل جوهرة وأخرى مربّعان: تحرّك، تحرّك، التقط.","Put a pick up block right after the second move inside the repeat.":"ضع لبنة التقط مباشرة بعد الحركة الثانية داخل كرّر.","Bolt picks up a gem on every second square. A good loop body is...":"يلتقط بولت جوهرة كل مربّعين. جسم الحلقة المناسب هو...","move, move, pick":"تحرّك، تحرّك، التقط","pick, pick":"التقط، التقط","Four gems in a row: what two blocks repeat?":"أربع جواهر في صف: ما اللبنتان اللتان تتكرّران؟","Move then pick, four times. After the loop, Bolt still needs to turn and go up.":"تحرّك ثم التقط، أربع مرات. بعد الحلقة، ما زال بولت يحتاج إلى أن يستدير ويصعد.","Move then pick up inside the repeat: one pair per gem.":"تحرّك ثم التقط داخل كرّر: زوج واحد لكل جوهرة.","Repeat 4 with move and pick inside picks up...":"كرّر 4 وبداخلها تحرّك والتقط تلتقط...","4 gems":"4 جواهر","2 gems":"جوهرتين","8 gems":"8 جواهر","The loop will say repeat 4 with move and pick inside. How many gems will Bolt pick up?":"الحلقة ستكون كرّر 4 وبداخلها تحرّك والتقط. كم جوهرة سيلتقط بولت؟","Five gems in a row: what two blocks repeat?":"خمس جواهر في صف: ما اللبنتان اللتان تتكرّران؟","Move then pick, five times. Then one more move before the turn.":"تحرّك ثم التقط، خمس مرات. ثم حركة أخرى قبل الاستدارة.","Repeat 5 with move and pick inside: how many move steps run?":"كرّر 5 وبداخلها تحرّك والتقط: كم خطوة تحرّك ستعمل؟","Bolt drives round the room. Which steps come again?":"يقود بولت حول الغرفة. أي الخطوات تعود مرة أخرى؟","Each side is three moves, a pick and a turn right. The last side has no gem.":"كل ضلع هو ثلاث حركات والتقاط واستدارة يمينًا. الضلع الأخير بلا جوهرة.","One side is three moves, pick up, turn right. Put that inside the repeat.":"الضلع الواحد ثلاث حركات، والتقط، واستدر يمينًا. ضع ذلك داخل كرّر.","After a loop ends, Bolt...":"بعد انتهاء الحلقة، بولت...","carries on with the blocks after the loop":"يواصل مع اللبنات التي بعد الحلقة","goes back to the start":"يعود إلى البداية","stops for good":"يتوقّف نهائيًا","The path zigzags. What is one zig?":"المسار متعرّج. ما هو التعرّج الواحد؟","One zig is: move, move, turn right, move, turn left.":"التعرّج الواحد هو: تحرّك، تحرّك، استدر يمينًا، تحرّك، استدر يسارًا.","Put one zig inside the repeat and set its number to the number of zigs.":"ضع تعرّجًا واحدًا داخل كرّر واجعل رقمه عدد التعرّجات.","The repeat count is how many times...":"عدد التكرار هو كم مرة...","the whole bracket runs":"يعمل القوس كله","Bolt turns":"يستدير بولت","you tap Run":"تنقر شغّل","A long staircase. How many stairs?":"سلّم طويل. كم درجة فيه؟","One stair: move, turn right, move, turn left. Count the stairs for the repeat number.":"الدرجة الواحدة: تحرّك، استدر يمينًا، تحرّك، استدر يسارًا. عُدّ الدرجات لتعرف عدد التكرار.","Put one stair inside the repeat and count the stairs for its number.":"ضع درجة واحدة داخل كرّر، وعُدّ الدرجات لتعرف رقمها.","A loop saved you blocks because...":"وفّرت عليك الحلقة لبنات لأن...","the same steps were written once and run many times":"الخطوات نفسها كُتبت مرة واحدة وعملت مرات كثيرة","Bolt skipped squares":"بولت تخطّى مربّعات","turns are free":"الاستدارات مجانية","A loop inside a loop":"حلقة داخل حلقة","The inner loop makes one stair. The outer loop makes the staircase. To know how many moves really ran, multiply: 3 stairs with 2 moves each is 6 moves.":"الحلقة الداخلية تصنع درجة واحدة. والحلقة الخارجية تصنع السلّم. لتعرف كم حركة عملت فعلًا، اضرب: 3 درجات في كل منها حركتان تساوي 6 حركات.","Each stair goes up two, then across one. Can a loop make the up part?":"كل درجة تصعد مربّعين، ثم تعبر مربّعًا واحدًا. هل تستطيع حلقة أن تصنع جزء الصعود؟","Put repeat 2 with a move inside the outer repeat. Then turn right, move, turn left.":"ضع كرّر 2 وبداخلها تحرّك داخل كرّر الخارجية. ثم استدر يمينًا، تحرّك، استدر يسارًا.","Inside the outer repeat, start with repeat 2 holding one move: that is the up part of a stair.":"داخل كرّر الخارجية، ابدأ بـ كرّر 2 وفيها حركة واحدة: هذا هو جزء الصعود في الدرجة.","Repeat 3 with repeat 2 with move inside: how many moves run?":"كرّر 3 وبداخلها كرّر 2 وبداخلها تحرّك: كم حركة ستعمل؟","Two rows of gems. What does Bolt do for one row?":"صفّان من الجواهر. ماذا يفعل بولت في الصف الواحد؟","One row: pick three gems, turn and come back, then step down. The outer loop does that for both rows.":"الصف الواحد: التقط ثلاث جواهر، استدر وعُد، ثم انزل خطوة. الحلقة الخارجية تفعل ذلك للصفّين.","Start with the inner part: repeat 3 with move and pick up clears one row.":"ابدأ بالجزء الداخلي: كرّر 3 مع تحرّك والتقط تنظّف صفًا واحدًا.","In a nested loop, the inner loop...":"في الحلقة المتداخلة، الحلقة الداخلية...","runs completely every time the outer loop runs once":"تعمل كاملة في كل مرة تعمل فيها الحلقة الخارجية مرة واحدة","runs only once":"تعمل مرة واحدة فقط","runs after the outer loop ends":"تعمل بعد انتهاء الحلقة الخارجية","Each stair has two gems going up.":"كل درجة فيها جوهرتان في الصعود.","The inner loop climbs and picks twice; the outer loop makes three stairs.":"الحلقة الداخلية تصعد وتلتقط مرتين؛ والحلقة الخارجية تصنع ثلاث درجات.","The inner loop is repeat 2 with move and pick up: that climbs one stair.":"الحلقة الداخلية هي كرّر 2 مع تحرّك والتقط: هذا يصعد درجة واحدة.","Repeat 3 with repeat 2 with move and pick inside picks up...":"كرّر 3 وبداخلها كرّر 2 وبداخلها تحرّك والتقط تلتقط...","6 gems":"6 جواهر","5 gems":"5 جواهر","3 gems":"3 جواهر","Par challenge: six blocks or fewer. Bolt goes round a square of three.":"تحدّي الحد الأدنى: ست لبنات أو أقل. يدور بولت حول مربّع ضلعه ثلاثة.","Three sides are the same: repeat 3 with move inside, then turn right. The last side is shorter.":"ثلاثة أضلاع متشابهة: كرّر 3 وبداخلها تحرّك، ثم استدر يمينًا. الضلع الأخير أقصر.","One side is repeat 3 with move. Put that and a turn right inside an outer repeat.":"الضلع الواحد هو كرّر 3 مع تحرّك. ضع ذلك مع استدر يمينًا داخل كرّر خارجية.","Which program is shortest for three equal sides and one short side?":"أي برنامج هو الأقصر لثلاثة أضلاع متساوية وضلع واحد قصير؟","A loop of loops, then a small loop":"حلقة من الحلقات، ثم حلقة صغيرة","Twelve move blocks":"اثنتا عشرة لبنة تحرّك","One big repeat 12":"كرّر 12 واحدة كبيرة","A conditional chooses":"الشرط يختار","An if block asks a question about the world: is the path ahead clear? If yes, the blocks inside run. If no, the else blocks run. The program checks again every time.":"لبنة إذا تسأل سؤالًا عن العالم: هل الطريق أمامك مفتوح؟ إذا كان الجواب نعم، تعمل اللبنات التي بداخلها. وإذا كان لا، تعمل لبنات وإلا. يعيد البرنامج السؤال في كل مرة.","What should Bolt do when the path ahead is blocked?":"ماذا يجب أن يفعل بولت عندما يكون الطريق أمامه مسدودًا؟","Inside the loop: if path ahead, move; else, turn left.":"داخل الحلقة: إذا الطريق مفتوح، تحرّك؛ وإلا، استدر يسارًا.","Put the if / else block inside the repeat. Move goes in the if part.":"ضع لبنة إذا / وإلا داخل كرّر. تحرّك تذهب في جزء إذا.","An if block...":"لبنة إذا...","checks a condition and chooses what to run":"تفحص شرطًا وتختار ما يعمل","repeats blocks":"تكرّر اللبنات","moves Bolt":"تحرّك بولت","An event starts a piece of program":"الحدث يبدأ جزءًا من البرنامج","A when block waits for something to happen in the world. When Bolt picks up a gem, the blocks inside run right then. An if asks; a when listens.":"لبنة عندما تنتظر حدوث شيء ما في العالم. عندما يلتقط بولت جوهرة، تعمل اللبنات التي بداخلها في الحال. لبنة إذا تسأل؛ ولبنة عندما تُصغي.","Every gem sits on a corner. What should happen when Bolt picks one up?":"كل جوهرة تقع على زاوية. ماذا يجب أن يحدث عندما يلتقط بولت واحدة؟","A when gem block with turn right inside. The loop keeps moving and picking.":"لبنة عندما جوهرة وبداخلها استدر يمينًا. والحلقة تواصل التحرّك والالتقاط.","Put turn right inside the when gem block.":"ضع استدر يمينًا داخل لبنة عندما تُلتقط جوهرة.","What is the difference between if and when?":"ما الفرق بين إذا وعندما؟","If asks a question now; when waits for something to happen":"إذا تطرح سؤالًا الآن؛ وعندما تنتظر حدوث شيء ما","They are the same":"هما الشيء نفسه","When is for turning only":"عندما للاستدارة فقط","The corner is in a different place each time. Can Bolt feel it?":"الزاوية في مكان مختلف في كل مرة. هل يستطيع بولت أن يتحسّسها؟","Repeat until goal. Inside: if path ahead move, else turn left.":"كرّر حتى الهدف. بداخلها: إذا الطريق مفتوح تحرّك، وإلا استدر يسارًا.","Inside repeat until goal, put an if / else with move in the if part.":"داخل كرّر حتى الهدف، ضع إذا / وإلا وفي جزء إذا تحرّك.","Why did a fixed list of moves fail on one of the boards?":"لماذا فشلت قائمة الحركات الثابتة على إحدى اللوحات؟","The corner moved, and the list could not notice":"تغيّر مكان الزاوية، ولم تستطع القائمة ملاحظة ذلك","Bolt was too slow":"كان بولت بطيئًا جدًا","The goal disappeared":"اختفى الهدف","The paint marks the corners. What should Bolt do on paint?":"الطلاء يحدّد الزوايا. ماذا يجب أن يفعل بولت على الطلاء؟","Move, then: if on paint, turn right. Keep going until the goal.":"تحرّك، ثم: إذا على طلاء، استدر يمينًا. واصل حتى الهدف.","Inside the loop: move first, then an if on paint block.":"داخل الحلقة: تحرّك أولًا، ثم لبنة إذا على طلاء.","On every loop turn, the if block...":"في كل دورة من الحلقة، لبنة إذا...","asks its question again":"يطرح سؤاله من جديد","asks only on the first turn":"يسأل في الدور الأول فقط","never asks":"لا يسأل أبدًا","Bolt is going to bump. Can a bump be useful?":"بولت سيصطدم. هل يمكن أن يكون الاصطدام مفيدًا؟","A when bump block with turn left inside. Then just keep moving until the goal.":"لبنة عندما اصطدام وبداخلها استدر يسارًا. ثم فقط واصل التحرّك حتى الهدف.","Put turn left inside the when bump block.":"ضع استدر يسارًا داخل لبنة عندما يصطدم بولت.","A when bump block runs...":"لبنة عندما اصطدام تعمل...","each time Bolt bumps into something":"في كل مرة يصطدم فيها بولت بشيء","once at the start":"مرة واحدة في البداية","when you press Run":"عندما تضغط شغّل","The gems are on different squares each time. When should Bolt pick?":"الجواهر على مربّعات مختلفة في كل مرة. متى يجب أن يلتقط بولت؟","Only pick when there is a gem: if on a gem, pick. Then move.":"التقط فقط عندما تكون هناك جوهرة: إذا على جوهرة، التقط. ثم تحرّك.","Put pick up inside an if on a gem block, then one move after it.":"ضع التقط داخل لبنة إذا على جوهرة، ثم حركة واحدة بعدها.","Pick up with no gem under Bolt is...":"الالتقاط دون جوهرة تحت بولت هو...","a mistake: check first with if":"خطأ: افحص أولًا بلبنة إذا","fine":"لا بأس به","a way to find gems":"طريقة للعثور على الجواهر","One program for three different mazes. What is the rule at every wall?":"برنامج واحد لثلاث متاهات مختلفة. ما القاعدة عند كل جدار؟","If the path ahead is clear, move. Else, turn right. Until the goal.":"إذا كان الطريق أمامك مفتوحًا، تحرّك. وإلا، استدر يمينًا. حتى الهدف.","One program solved three mazes because...":"برنامج واحد حلّ ثلاث متاهات لأنه...","it checked the wall every step instead of counting":"فحص الجدار في كل خطوة بدلًا من العدّ","the mazes were the same":"المتاهات كانت متشابهة","it was long":"كان طويلًا","AND, OR and NOT":"و، أو، ليس","Two questions can be joined. Wall ahead AND on a gem is true only when both are true. Wall OR paint is true when either is. NOT flips an answer.":"يمكن ربط سؤالين معًا. «جدار أمامي و على جوهرة» صحيح فقط عندما يكون كلاهما صحيحًا. «جدار أو طلاء» صحيح عندما يكون أحدهما صحيحًا. و«ليس» تقلب الجواب.","A gem on a corner means turn right. A bare corner means turn left. How does Bolt tell them apart?":"جوهرة على زاوية تعني استدر يمينًا. زاوية خالية تعني استدر يسارًا. كيف يميّز بولت بينهما؟","If wall ahead AND on a gem: pick, turn right. Else if wall ahead: turn left. Else: move.":"إذا جدار أمامي و على جوهرة: التقط، استدر يمينًا. وإلا إذا جدار أمامي: استدر يسارًا. وإلا: تحرّك.","Make the first if ask two things: wall ahead and on a gem.":"اجعل إذا الأولى تسأل عن أمرين: جدار أمامي وعلى جوهرة.","Wall ahead AND on a gem is true when...":"«جدار أمامي و على جوهرة» صحيح عندما...","both are true":"يكون كلاهما صحيحًا","either one is true":"يكون أحدهما صحيحًا","neither is true":"لا يكون أيٌّ منهما صحيحًا","Some corners have a wall, some have paint. Bolt turns right at both.":"بعض الزوايا فيها جدار، وبعضها فيها طلاء. بولت يستدير يمينًا عند كليهما.","Move first. Then: if NOT path ahead OR on paint, turn right.":"تحرّك أولًا. ثم: إذا ليس الطريق مفتوح أو على طلاء، استدر يمينًا.","Build the question first: not path ahead, then or, then on paint.":"ابنِ السؤال أولًا: ليس الطريق مفتوح، ثم أو، ثم على طلاء.","NOT path ahead OR on paint is true when...":"«ليس الطريق مفتوح أو على طلاء» صحيح عندما...","the way is blocked, or Bolt stands on paint, or both":"يكون الطريق مسدودًا، أو يقف بولت على طلاء، أو كلاهما","only when both happen":"يحدث كلاهما فقط","never":"أبدًا","One program, three mazes. What is the rule at every wall?":"برنامج واحد، ثلاث متاهات. ما القاعدة عند كل جدار؟","Put the if inside the loop so it is checked at every step.":"ضع لبنة إذا داخل الحلقة حتى تُفحص في كل خطوة.","An if inside a loop is checked...":"لبنة إذا داخل الحلقة تُفحص...","every time round the loop":"في كل دورة من الحلقة","only once":"مرة واحدة فقط","at the end":"في النهاية","The door needs the key, and the key is somewhere on the way.":"الباب يحتاج إلى المفتاح، والمفتاح في مكان ما على الطريق.","If there is something to pick up, pick it. Then the usual: if path move, else turn right.":"إذا كان هناك شيء لالتقاطه، التقطه. ثم المعتاد: إذا طريق تحرّك، وإلا استدر يمينًا.","Start the loop with an if something to pick up block holding pick up.":"ابدأ الحلقة بلبنة إذا شيء لالتقاطه وفيها التقط.","The door opened because...":"انفتح الباب لأن...","Bolt had picked up the key before reaching it":"بولت التقط المفتاح قبل الوصول إليه","Bolt bumped it":"بولت اصطدم به","doors always open":"الأبواب تنفتح دائمًا","A variable is a labeled box":"المتغيّر صندوق عليه اسم","A variable is a box with a name. Set puts a number in the box. Change by adds to it. The watch pill shows what is inside right now. This door opens only when the count box says the number written on the door.":"المتغيّر صندوق له اسم. اضبط تضع رقمًا في الصندوق. غيّر بمقدار تضيف إليه. شارة المراقبة تُظهر ما في داخله الآن. هذا الباب لا يُفتح إلا عندما يحمل الصندوق count الرقم المكتوب على الباب.","How will Bolt know it has five gems?":"كيف سيعرف بولت أن معه خمس جواهر؟","Set count to 0 first. Each time Bolt picks a gem, change count by 1.":"اضبط count على 0 أولًا. وفي كل مرة يلتقط فيها بولت جوهرة، غيّر count بمقدار 1.","Put change count by 1 right after the pick up inside the repeat.":"ضع غيّر count بمقدار 1 مباشرة بعد التقط داخل كرّر.","Change count by 1 means...":"غيّر count بمقدار 1 تعني...","add 1 to what is in the box":"أضف 1 إلى ما في الصندوق","put 1 in the box":"ضع 1 في الصندوق","empty the box":"أفرغ الصندوق","How will Bolt know it has seven gems? And what will you call the box?":"كيف سيعرف بولت أن معه سبع جواهر؟ وماذا ستسمّي الصندوق؟","Pick a name a partner would understand, like count. Set it to 0, then change it by 1 for each gem.":"اختر اسمًا يفهمه زميلك، مثل count. اضبطه على 0، ثم غيّره بمقدار 1 لكل جوهرة.","Name the box count, then put change count by 1 right after the pick up.":"سمِّ الصندوق count، ثم ضع غيّر count بمقدار 1 مباشرة بعد التقط.","The door opens when the box holds the true number of gems. The number changes each time.":"الباب يفتح عندما يحمل الصندوق العدد الحقيقي للجواهر. والعدد يتغيّر في كل مرة.","Count only when there really is a gem: if on a gem, pick and change count by 1.":"عُدّ فقط عندما تكون هناك جوهرة فعلًا: إذا على جوهرة، التقط وغيّر count بمقدار 1.","Inside the if on a gem block: pick up, then change count by 1.":"داخل لبنة إذا على جوهرة: التقط، ثم غيّر count بمقدار 1.","What is in the count box at the end?":"ما الذي في صندوق count في النهاية؟","The number of gems Bolt picked up":"عدد الجواهر التي التقطها بولت","Always 5":"دائمًا 5","The number of moves":"عدد الحركات","This door opens when the steps box reaches 0. Start high, count down.":"هذا الباب يفتح عندما يصل صندوق steps إلى 0. ابدأ بعدد كبير، وعُدّ تنازليًا.","Set steps to 4. Each time round, change steps by -1 before you move.":"اضبط steps على 4. وفي كل دورة، غيّر steps بمقدار -1 قبل أن تتحرّك.","Set steps to the number of squares before the door, then change it by -1 inside the loop.":"اضبط steps على عدد المربعات قبل الباب، ثم غيّره بمقدار -1 داخل الحلقة.","Set empties the box and puts in a new number. Change...":"اضبط تفرغ الصندوق وتضع فيه عددًا جديدًا. أما غيّر...","adds to or takes from what is there":"فتضيف إلى ما فيه أو تنقص منه","does the same as set":"فتفعل مثل اضبط تمامًا","deletes the box":"فتحذف الصندوق","Set steps to 6. Each time round, change steps by -1 before you move.":"اضبط steps على 6. وفي كل دورة، غيّر steps بمقدار -1 قبل أن تتحرّك.","This door opens after exactly two bumps. Who counts them?":"هذا الباب يفتح بعد اصطدامين بالضبط. من يعدّهما؟","When bump: change bumps by 1 and turn right. The loop just moves.":"عندما اصطدام: غيّر bumps بمقدار 1 واستدر يمينًا. والحلقة تتحرّك فقط.","Put change bumps by 1 inside the when bump block, before the turn.":"ضع غيّر bumps بمقدار 1 داخل لبنة عندما يصطدم بولت، قبل الاستدارة.","The bumps box went up because...":"ارتفع صندوق bumps لأن...","the when bump block changed it each time":"لبنة عندما اصطدام غيّرته في كل مرة","Bolt moved":"بولت تحرّك","it counts on its own":"هو يعدّ من تلقاء نفسه","Two boxes at once":"صندوقان في وقت واحد","A program can keep many boxes. Here gems counts the gems and turns counts the corners. Each box has its own name, so you always know which is which.":"يمكن للبرنامج أن يحتفظ بصناديق كثيرة. هنا gems يعدّ الجواهر و turns يعدّ الزوايا. لكل صندوق اسمه الخاص، فتعرف دائمًا أيهما أيّ.","Two things to count: gems and turns. Two boxes.":"شيئان نعدّهما: الجواهر والاستدارات. صندوقان.","When bump: change turns by 1 and turn right. In the loop: if on a gem, pick and change gems by 1.":"عندما اصطدام: غيّر turns بمقدار 1 واستدر يمينًا. في الحلقة: إذا على جوهرة، التقط وغيّر gems بمقدار 1.","Set both boxes to 0 first. Then change gems by 1 goes right after the pick up.":"اضبط الصندوقين على 0 أولًا. ثم غيّر gems بمقدار 1 تأتي مباشرة بعد التقط.","Why give each box its own name?":"لماذا نعطي كل صندوق اسمه الخاص؟","So you know which number is which":"حتى تعرف أي عدد يخصّ ماذا","Boxes need names to exist":"الصناديق تحتاج إلى أسماء كي توجد","Names make Bolt faster":"الأسماء تجعل بولت أسرع","Gems in different places, a corner, and a door that wants the true count.":"جواهر في أماكن مختلفة، وزاوية، وباب يريد العدد الحقيقي.","When bump: turn left. In the loop: if on a gem, pick and change count by 1. Then move.":"عندما اصطدام: استدر يسارًا. في الحلقة: إذا على جوهرة، التقط وغيّر count بمقدار 1. ثم تحرّك.","Put change count by 1 right after the pick up, inside the if on a gem block.":"ضع غيّر count بمقدار 1 مباشرة بعد التقط، داخل لبنة إذا على جوهرة.","A variable is useful when...":"المتغيّر مفيد عندما...","a number changes while the program runs":"يتغيّر عدد أثناء عمل البرنامج","the number never changes":"لا يتغيّر العدد أبدًا","there are no gems":"لا توجد جواهر","Three kinds of boxes":"ثلاثة أنواع من الصناديق","A number box holds a count. A flag box is a true/false (Boolean) box: on or off, like hasKey. A word box holds a word from a list, like color. Pick the kind that fits what you store.":"صندوق الرقم يحمل عددًا. صندوق العَلَم صندوق صح/خطأ (منطقي): مشغّل أو مطفأ، مثل hasKey. صندوق الكلمة يحمل كلمة من قائمة، مثل color. اختر النوع الذي يناسب ما تخزّنه.","The door reads a flag: hasKey must be on, and Bolt must really hold the key. When does the flag become true?":"الباب يقرأ راية: يجب أن يكون hasKey مشغّلًا، وأن يحمل بولت المفتاح فعلًا. متى تصبح الراية صحيحة؟","Set hasKey off at the start. When Bolt picks the key up, set hasKey on.":"اضبط hasKey على مطفأ في البداية. وعندما يلتقط بولت المفتاح، اضبط hasKey على مشغّل.","Right after the pick up, add set hasKey to on.":"مباشرة بعد التقط، أضف اضبط hasKey على مشغّل.","A flag variable holds...":"متغيّر الراية يحمل...","on or off":"مشغّل أو مطفأ","any number":"أي عدد","a picture":"صورة","The door shows the word it wants. Which box holds words?":"الباب يعرض الكلمة التي يريدها. أي صندوق يحمل الكلمات؟","Set color to the word on the door, then drive.":"اضبط color على الكلمة التي على الباب، ثم قُد.","Start with a set block: color gets the word written on the door.":"ابدأ بلبنة اضبط: color يأخذ الكلمة المكتوبة على الباب.","A word variable holds...":"متغيّر الكلمة يحمل...","a word from a list":"كلمة من قائمة","a number":"عددًا","This program works, but a partner cannot read it. What is x?":"هذا البرنامج يعمل، لكن زميلك لا يستطيع قراءته. ما هو x؟","Tap a set or change block and give the box a name that says what it holds.":"انقر لبنة اضبط أو غيّر وأعطِ الصندوق اسمًا يدلّ على ما يحمله.","Rename x to count in every block that uses it.":"غيّر اسم x إلى count في كل لبنة تستخدمه.","Why is x a bad name here?":"لماذا x اسم سيئ هنا؟","It does not say what the box holds":"لأنه لا يدلّ على ما يحمله الصندوق","It is too long":"لأنه طويل جدًا","Letters are not allowed":"لأن الحروف غير مسموح بها","Name a group of steps once, use it everywhere":"سمِّ مجموعة خطوات مرة واحدة، واستخدمها في كل مكان","A My Block is a group of steps with a name. Make it once; then a call block runs the whole group wherever you put it. Here the block Stair is already made for you: call it for every stair.":"لبنتي هي مجموعة خطوات لها اسم. اصنعها مرة واحدة؛ ثم تشغّل لبنة استدعِ المجموعة كلها أينما وضعتها. هنا اللبنة Stair جاهزة لك: استدعِها لكل درجة.","The block Stair is already made. How do you run it?":"اللبنة Stair جاهزة. كيف تشغّلها؟","Tap call on the shelf: one call runs everything inside Stair.":"انقر استدعِ على الرفّ: استدعاء واحد يشغّل كل ما داخل Stair.","Add one call Stair block and run it: Bolt climbs one stair.":"أضف لبنة استدعِ Stair واحدة وشغّلها: يصعد بولت درجة واحدة.","A My Block is...":"لبنتي هي...","a group of steps with a name you can use again":"مجموعة خطوات لها اسم يمكنك استخدامها مرة أخرى","a kind of wall":"نوع من الجدران","the goal flag":"علم الهدف","A procedure is a group of steps with a name. Define it once; a call runs the whole group. Three identical rooms, one block named Room: call it three times, then one more move to the goal.":"الإجراء هو مجموعة خطوات لها اسم. عرّفه مرة واحدة؛ والاستدعاء يشغّل المجموعة كلها. ثلاث غرف متطابقة، ولبنة واحدة اسمها Room: استدعِها ثلاث مرات، ثم حركة أخرى إلى الهدف.","The block Room is already made. How do you run it?":"اللبنة Room جاهزة. كيف تشغّلها؟","Tap call on the shelf: one call runs everything inside Room.":"انقر استدعِ على الرفّ: استدعاء واحد يشغّل كل ما داخل Room.","Add one call Room block and run it: Bolt clears one room.":"أضف لبنة استدعِ Room واحدة وشغّلها: ينظّف بولت غرفة واحدة.","A procedure is...":"الإجراء هو...","Bolt drives round three sides of a square. What is one side?":"يقود بولت حول ثلاثة أضلاع من مربّع. ما هو الضلع الواحد؟","The block Side is one side and a turn. After three calls Bolt still needs two moves.":"اللبنة Side هي ضلع واحد واستدارة. بعد ثلاثة استدعاءات ما زال بولت يحتاج إلى حركتين.","Add call Side once and watch what one call does.":"أضف استدعِ Side مرة واحدة وشاهد ماذا يفعل استدعاء واحد.","What does a call block do?":"ماذا تفعل لبنة استدعِ؟","Runs all the steps inside the named block":"تشغّل كل الخطوات داخل اللبنة المسمّاة","Deletes the block":"تحذف اللبنة","Makes Bolt call for help":"تجعل بولت يطلب المساعدة","Three sides of a big square. Make one block for a side.":"ثلاثة أضلاع من مربّع كبير. اصنع لبنة واحدة للضلع.","Inside Side: repeat 5 with move, then turn right. Call it three times.":"داخل Side: كرّر 5 وبداخلها تحرّك، ثم استدر يمينًا. استدعِها ثلاث مرات.","Make My Block Side first: one side is a repeat with move inside, then a turn right.":"اصنع لبنتي Side أولًا: الضلع الواحد كرّر بداخلها تحرّك، ثم استدر يمينًا.","This route has two legs. What would you name each leg?":"هذا المسار من جزأين. ماذا ستسمّي كل جزء؟","Make one block for going up and one for going across. Then call both.":"اصنع لبنة للصعود ولبنة للعبور. ثم استدعِ كليهما.","Make My Block Up with four moves inside, then call it.":"اصنع لبنتي Up وفيها أربع حركات، ثم استدعِها.","Why split a long route into named parts?":"لماذا نقسّم المسار الطويل إلى أجزاء مسمّاة؟","Each part is easier to check and to use again":"لأن كل جزء أسهل في التحقّق وإعادة الاستخدام","Bolt drives faster":"لأن بولت يقود أسرع","You must use more blocks":"لأنك يجب أن تستخدم لبنات أكثر","A parameter: one block, many jobs":"المُعامِل: لبنة واحدة، مهام كثيرة","These rooms have different depths. Instead of three blocks, make one block Room that takes a number: steps. Inside, repeat steps times. Each call gives its own number: Room(1), Room(3), Room(2).":"هذه الغرف أعماقها مختلفة. بدلًا من ثلاث لبنات، اصنع لبنة واحدة Room تأخذ عددًا: steps. بداخلها، كرّر steps مرة. كل استدعاء يعطي عدده الخاص: Room(1)، Room(3)، Room(2).","The rooms are 1, 3 and 2 deep. One block for all three?":"أعماق الغرف 1 و3 و2. لبنة واحدة للثلاث كلها؟","Give Room a number, steps. Inside, repeat steps with move, both going in and coming back.":"أعطِ Room عددًا، steps. بداخلها، كرّر steps وبداخلها تحرّك، في الدخول وفي العودة.","Give Room a number: tap the block, choose Takes a number, then use steps in its repeat.":"أعطِ Room رقمًا: اضغط اللبنة، واختر تأخذ عددًا، ثم استخدم steps في كرّر الخاصة بها.","A parameter lets one block...":"المُعامِل يتيح للبنة واحدة أن...","do the same job with a different number each time":"تؤدّي المهمة نفسها بعدد مختلف في كل مرة","run without being called":"تعمل دون أن تُستدعى","change the board":"تغيّر اللوحة","Remix a starter block":"اعمل ريمكس للبنة جاهزة","The Starter blocks shelf gives you blocks other people made. You may change them: that is a remix. Keep the line that says where the block came from, so everyone knows who started it.":"رفّ اللبنات الجاهزة يعطيك لبنات صنعها آخرون. يمكنك تغييرها: وهذا هو الريمكس. أبقِ السطر الذي يذكر من أين جاءت اللبنة، حتى يعرف الجميع من بدأها.","Zig climbs one square, then steps across. These stairs are two squares tall.":"Zig تصعد مربّعًا واحدًا، ثم تعبر. هذه الدرجات ارتفاعها مربّعان.","Open Zig and add one more move at the start. Keep its credit line on.":"افتح Zig وأضف تحرّك واحدة أخرى في البداية. أبقِ سطر المصدر فيها.","After the remix, call Zig twice: one call per stair.":"بعد إعادة المزج، استدعِ Zig مرتين: استدعاء واحد لكل درجة.","When you remix a block someone else made, you...":"عندما تعمل ريمكس للبنة صنعها شخص آخر، فإنك...","change it and keep the line saying where it came from":"تغيّرها وتُبقي السطر الذي يذكر من أين جاءت","must never change it":"يجب ألا تغيّرها أبدًا","delete the credit line":"تحذف سطر المصدر","Every straight run ends with a right turn. Only the length changes.":"كل مقطع مستقيم ينتهي باستدارة يمينًا. الطول فقط هو ما يتغيّر.","Make Dash(n): repeat n move, then turn right. Call it with each length.":"اصنع Dash(n): كرّر n تحرّك، ثم استدر يمينًا. استدعِها بكل طول.","Inside Dash, set the repeat to Use n. Then call Dash with 7 for the first run.":"داخل Dash، اجعل كرّر على استخدم n. ثم استدعِ Dash بالرقم 7 للجزء الأول.","Dash(7) and Dash(3) run the same block with...":"Dash(7) و Dash(3) تشغّلان اللبنة نفسها مع...","a different number":"عدد مختلف","a different robot":"روبوت مختلف","no difference":"لا فرق","The starter blocks almost fit. Which one is one step short?":"اللبنات الجاهزة تكاد تناسب. أيها تنقصه خطوة واحدة؟","Dash is three moves; this corridor is four. Remix Dash, keep the credit line.":"Dash هي ثلاث حركات؛ وهذا الممرّ أربعة. اعمل ريمكس لـ Dash، وأبقِ سطر المصدر.","Add one more move to Dash, then start the program with call Dash.":"أضف حركة واحدة أخرى إلى Dash، ثم ابدأ البرنامج بـ استدعِ Dash.","A remix is...":"الريمكس هو...","someone else's block, changed to fit a new job":"لبنة شخص آخر، غُيّرت لتناسب مهمة جديدة","a brand new block":"لبنة جديدة تمامًا","a mistake":"خطأ","Three subgoals":"ثلاثة أهداف فرعية","A big job is easier as three small ones: collect the gems, climb the stairs, cross to the goal. Make one block for each subgoal and give it a name that says what it does. Then the main program is just three calls.":"المهمة الكبيرة أسهل كثلاث مهام صغيرة: اجمع الجواهر، اصعد الدرجات، اعبر إلى الهدف. اصنع لبنة لكل هدف فرعي وأعطها اسمًا يدلّ على ما تفعله. عندها يصبح البرنامج الرئيسي ثلاثة استدعاءات فقط.","Name the three parts of this route before you build anything.":"سمِّ أجزاء هذا المسار الثلاثة قبل أن تبني أي شيء.","One block collects the gems, one climbs, one crosses. The main program calls them in order.":"لبنة تجمع الجواهر، ولبنة تصعد، ولبنة تعبر. والبرنامج الرئيسي يستدعيها بالترتيب.","Make the first block GetGems: a repeat with move and pick up inside.":"اجعل اللبنة الأولى GetGems: كرّر وبداخلها تحرّك والتقط.","Decomposition means...":"التجزئة تعني...","splitting a big problem into smaller parts":"تقسيم مشكلة كبيرة إلى أجزاء أصغر","making the program longer":"جعل البرنامج أطول","deleting blocks":"حذف اللبنات","Three legs: up, across, down. Which leg has the gem?":"ثلاثة أجزاء: صعود، عبور، نزول. أي جزء فيه الجوهرة؟","Make a block for each leg. Across picks up the gem halfway.":"اصنع لبنة لكل جزء. Across تلتقط الجوهرة في منتصف الطريق.","Three named legs make a program...":"ثلاثة أجزاء مسمّاة تجعل البرنامج...","easier to read and to fix":"أسهل في القراءة والإصلاح","slower":"أبطأ","impossible to run":"مستحيل التشغيل","Document it":"وثّقه","A note chip on a block tells a partner what the block does without reading every step. Pin the chip that matches each block: the level checks that your notes tell the truth.":"بطاقة الملاحظة على اللبنة تخبر زميلك بما تفعله اللبنة دون قراءة كل خطوة. ثبّت البطاقة التي تطابق كل لبنة: المستوى يتحقّق من أن ملاحظاتك صادقة.","Three blocks, three jobs: along the top, down the side, home. Each needs a note chip.":"ثلاث لبنات، ثلاث مهام: على طول الصف العلوي، نزولًا على الجانب، إلى البيت. كل واحدة تحتاج إلى بطاقة ملاحظة.","Open a block, tap Note chip and pick the sentence that says what it really does.":"افتح لبنة، انقر بطاقة ملاحظة واختر الجملة التي تصف ما تفعله فعلًا.","Sweep drives along the top collecting gems, so its chip is Picks up the gems.":"تسير Sweep على طول الأعلى وتجمع الجواهر، لذلك بطاقتها هي يلتقط الجواهر.","A note chip on a block should say...":"بطاقة الملاحظة على اللبنة يجب أن تذكر...","what the block does, truthfully":"ما تفعله اللبنة، بصدق","how many stars you have":"كم نجمة لديك","the name of the robot":"اسم الروبوت","The shelf block Zigzag was made by someone else. How many zigs does this staircase have?":"لبنة الرفّ Zigzag صنعها شخص آخر. كم تعرّجًا في هذا السلّم؟","Call Zigzag with 5. Then make your own block for the last two squares, with its own note chip. Leave the credit line on Zigzag alone.":"استدعِ Zigzag بالعدد 5. ثم اصنع لبنتك الخاصة للمربّعين الأخيرين، مع بطاقة ملاحظة خاصة بها. ولا تلمس سطر المصدر في Zigzag.","Start with call Zigzag and set its number to the number of zigs.":"ابدأ بـ استدعِ Zigzag واجعل رقمها عدد التعرّجات.","When you use a block someone else made, the credit line...":"عندما تستخدم لبنة صنعها شخص آخر، فإن سطر المصدر...","stays on, so everyone knows who made it":"يبقى، حتى يعرف الجميع من صنعها","should be deleted":"يجب أن يُحذف","makes Bolt slower":"يجعل بولت أبطأ","Expected and actual":"المتوقّع والفعلي","This program has a bug. Press Step to run it one block at a time and watch where Bolt first does something you did not expect. Fix only that block: the fewest edits earn the most stars.":"في هذا البرنامج خطأ برمجي. اضغط خطوة لتشغّله لبنة واحدة في كل مرة وراقب أين يفعل بولت أول شيء لم تتوقّعه. أصلح تلك اللبنة فقط: أقل عدد من التعديلات يكسب أكبر عدد من النجوم.","Step through it. At which block does Bolt first go the wrong way?":"نفّذه خطوة بخطوة. عند أي لبنة يسلك بولت الطريق الخطأ لأول مرة؟","After three moves Bolt should turn toward the flag. Which way is that?":"بعد ثلاث حركات يجب أن يستدير بولت نحو العلم. أي اتجاه هو ذلك؟","Change the turn left into turn right.":"غيّر استدر يسارًا إلى استدر يمينًا.","A bug is...":"الخطأ البرمجي هو...","a mistake in a program":"غلطة في البرنامج","an insect on the board":"حشرة على اللوحة","a kind of block":"نوع من اللبنات","Bolt bumps right at the end. One too many of what?":"يصطدم بولت في النهاية تمامًا. ما الذي زاد واحدًا؟","Count the squares between Bolt and the flag, then look at the repeat number.":"عُدّ المربّعات بين بولت والعلم، ثم انظر إلى عدد التكرار.","Change the repeat from 6 to 5.":"غيّر التكرار من 6 إلى 5.","Bolt bumped the wall one step after the flag. The bug is...":"اصطدم بولت بالجدار بعد خطوة من العلم. الخطأ البرمجي هو أن...","the loop runs one time too many":"الحلقة تعمل مرة زائدة","the flag is in the wrong place":"العلم في المكان الخطأ","move is broken":"لبنة تحرّك معطّلة","Bolt reached the flag but the level is not done. What is still on the board?":"وصل بولت إلى العلم لكن المستوى لم يكتمل. ما الذي ما زال على اللوحة؟","Bolt drove over the gem. Which block is missing, and where?":"مرّ بولت فوق الجوهرة. أي لبنة ناقصة، وأين؟","Add a pick up after the second move.":"أضف التقط بعد الحركة الثانية.","Bolt finished on the flag but a gem was left. The fix is...":"أنهى بولت على العلم لكن بقيت جوهرة. الإصلاح هو...","add the missing block in the right place":"إضافة اللبنة الناقصة في المكان الصحيح","delete everything and start again":"حذف كل شيء والبدء من جديد","add more moves":"إضافة مزيد من الحركات","Bolt turns when it should move and moves when it should turn. Look at the question in the if.":"يستدير بولت حين يجب أن يتحرّك ويتحرّك حين يجب أن يستدير. انظر إلى السؤال في لبنة إذا.","The if asks wall ahead. What should it ask so that yes means move?":"لبنة إذا تسأل: جدار أمامي. ماذا يجب أن تسأل حتى تعني نعم تحرّك؟","Change the condition from wall ahead to path ahead.":"غيّر الشرط من جدار أمامي إلى الطريق مفتوح.","The program moved when it should have turned. The bug was in...":"تحرّك البرنامج حين كان يجب أن يستدير. كان الخطأ البرمجي في...","the condition of the if":"شرط لبنة إذا","the number of gems":"عدد الجواهر","the color of Bolt":"لون بولت","All the right blocks are here. Is one of them in the wrong place?":"كل اللبنات الصحيحة هنا. هل إحداها في المكان الخطأ؟","Bolt turns too early. Move the turn right down one place.":"يستدير بولت مبكرًا جدًا. انقل استدر يمينًا مكانًا واحدًا لأسفل.","Move the turn right so it comes after the second move.":"انقل استدر يمينًا بحيث تأتي بعد الحركة الثانية.","Every block was right but the order was wrong. That is...":"كل لبنة كانت صحيحة لكن الترتيب كان خطأ. هذا...","still a bug: order matters":"ما زال خطأً برمجيًا: الترتيب مهم","fine: order never matters":"لا بأس به: الترتيب لا يهم أبدًا","impossible":"مستحيل","Step through one stair. Does Bolt end up facing the right way?":"نفّذ درجة واحدة خطوة بخطوة. هل ينتهي بولت وهو يواجه الاتجاه الصحيح؟","There is one block too many inside the loop. Which one?":"هناك لبنة زائدة داخل الحلقة. أيها؟","Delete the second turn left inside the repeat.":"احذف استدر يسارًا الثانية داخل كرّر.","An extra block inside a loop...":"اللبنة الزائدة داخل الحلقة...","runs every time round, so it breaks every stair":"تعمل في كل دورة، فتفسد كل درجة","does nothing":"لا تفعل شيئًا","Two bugs this time. Watch the first gem: which way should Bolt turn?":"خطآن برمجيان هذه المرة. راقب الجوهرة الأولى: في أي اتجاه يجب أن يستدير بولت؟","The when block turns the wrong way. And is the loop long enough to reach the flag?":"لبنة عندما تستدير في الاتجاه الخطأ. وهل الحلقة طويلة بما يكفي للوصول إلى العلم؟","Change left to right in the when block, and the repeat from 6 to 8.":"غيّر يسارًا إلى يمينًا في لبنة عندما، والتكرار من 6 إلى 8.","After fixing one bug Bolt still fails. You should...":"بعد إصلاح خطأ واحد ما زال بولت يفشل. يجب أن...","test again and look for the next bug":"تختبر مرة أخرى وتبحث عن الخطأ التالي","give up":"تستسلم","add random blocks":"تضيف لبنات عشوائية","Test cases":"حالات الاختبار","One program, three test boards. A fix must pass them all: the tabs above the board show a tick or a cross for each test after a run. Find the test that fails, step through it, and change as little as you can.":"برنامج واحد، ثلاث لوحات اختبار. يجب أن ينجح الإصلاح فيها كلها: التبويبات فوق اللوحة تعرض علامة صح أو خطأ لكل اختبار بعد التشغيل. اعثر على الاختبار الذي يفشل، نفّذه خطوة بخطوة، وغيّر أقل ما يمكن.","Which test board fails? Run and read the tabs.":"أي لوحة اختبار تفشل؟ شغّل واقرأ التبويبات.","At the corner Bolt turns the wrong way on every board. Which turn is it?":"عند الزاوية يستدير بولت في الاتجاه الخطأ على كل لوحة. أي استدارة هي؟","Change turn right to turn left in the else part.":"غيّر استدر يمينًا إلى استدر يسارًا في جزء وإلا.","Why test a program on more than one board?":"لماذا نختبر البرنامج على أكثر من لوحة؟","A bug may only show on some inputs":"لأن الخطأ قد يظهر مع بعض المدخلات فقط","It makes the program longer":"لأن ذلك يجعل البرنامج أطول","Bolt likes it":"لأن بولت يحب ذلك","Bolt reaches down on every square. What is wrong with that?":"يمدّ بولت يده في كل مربّع. ما الخطأ في ذلك؟","Pick up only when there is a gem: wrap the pick in an if.":"التقط فقط عندما تكون هناك جوهرة: ضع الالتقاط داخل لبنة إذا.","Put the pick up inside an if on a gem.":"ضع التقط داخل إذا على جوهرة.","Picking up where there is no gem is...":"الالتقاط حيث لا توجد جوهرة هو...","an error the tests catch":"خطأ تكشفه الاختبارات","always fine":"مقبول دائمًا","The door reads the count box. Watch the pill: does the box ever change?":"الباب يقرأ صندوق count. راقب الشارة: هل يتغيّر الصندوق أبدًا؟","Bolt picks gems but never counts them. Which block is missing inside the if?":"يلتقط بولت الجواهر لكنه لا يعدّها أبدًا. أي لبنة ناقصة داخل إذا؟","Add change count by 1 right after the pick up.":"أضف غيّر count بمقدار 1 مباشرة بعد التقط.","The watch pill never moved. That tells you...":"شارة المراقبة لم تتحرّك أبدًا. هذا يخبرك أن...","the variable is never changed":"المتغيّر لا يتغيّر أبدًا","the door is broken":"الباب معطّل","Bolt is slow":"بولت بطيء","Bolt turns right on a gem that is not at a corner. Read the first condition aloud.":"يستدير بولت يمينًا على جوهرة ليست عند زاوية. اقرأ الشرط الأول بصوت عالٍ.","Wall ahead OR on a gem is true too often. Which word should join the two questions?":"«جدار أمامي أو على جوهرة» صحيح أكثر مما ينبغي. أي كلمة يجب أن تربط السؤالين؟","Change or to and in the first if.":"غيّر أو إلى و في لبنة إذا الأولى.","OR was true too often. AND is true only when...":"«أو» كانت صحيحة أكثر مما ينبغي. «و» تكون صحيحة فقط عندما...","both parts are true":"يكون الجزءان صحيحين","either part is true":"يكون أحد الجزأين صحيحًا","Two boxes: gems and count. Which one does the door read?":"صندوقان: gems و count. أيهما يقرأ الباب؟","The program counts into the wrong box. Which block names count?":"البرنامج يعدّ في الصندوق الخطأ. أي لبنة تذكر count؟","Change count by 1 should be change gems by 1.":"غيّر count بمقدار 1 يجب أن تكون غيّر gems بمقدار 1.","The program counted into the wrong variable. The door...":"عدّ البرنامج في المتغيّر الخطأ. الباب...","read a box that stayed at 0":"قرأ صندوقًا بقي على 0","opened anyway":"انفتح على أي حال","counted for itself":"عدّ بنفسه","Tests 1 and 2 pass. What is different about test 3?":"الاختباران 1 و2 ينجحان. ما المختلف في الاختبار 3؟","Test 3 has no gems at all, so the count never reaches 2. When should the loop really stop?":"الاختبار 3 بلا جواهر إطلاقًا، لذا لا يصل العدد إلى 2 أبدًا. متى يجب أن تتوقّف الحلقة فعلًا؟","Change repeat until count = 2 into repeat until on the goal.":"غيّر كرّر حتى count = 2 إلى كرّر حتى على الهدف.","An edge case is...":"الحالة الحدّية هي...","an unusual input that breaks a hidden assumption":"مدخل غير معتاد يكسر افتراضًا خفيًا","the border of the board":"حافة اللوحة","a very long program":"برنامج طويل جدًا","Bolt reaches the goal on every board, but only by bumping into each corner. This level says: never bump.":"يصل بولت إلى الهدف على كل لوحة، لكن فقط بالاصطدام بكل زاوية. هذا المستوى يقول: لا تصطدم أبدًا.","Bolt only turns after a bump. Make it look before it moves: ask about the wall inside the loop.":"بولت يستدير فقط بعد الاصطدام. اجعله ينظر قبل أن يتحرّك: اسأل عن الجدار داخل الحلقة.","Inside the loop, before the move, add: if wall ahead, turn right.":"داخل الحلقة، قبل تحرّك، أضف: إذا جدار أمامي، استدر يمينًا.","Bolt reached the goal but bumped on the way. For this test that is...":"وصل بولت إلى الهدف لكنه اصطدم في الطريق. بالنسبة لهذا الاختبار هذا...","a fail: the rule was never bump":"فشل: القاعدة كانت لا تصطدم أبدًا","a pass":"نجاح","extra points":"نقاط إضافية","Two routes, one better":"مساران، أحدهما أفضل","Two programs can both reach the flag. Run each one and count: which is shorter, which has fewer blocks, which avoids trouble? Pick the better one, then make it better still.":"يمكن لبرنامجين أن يصلا كلاهما إلى العلم. شغّل كلًا منهما وعُدّ: أيهما أقصر، أيهما لبناته أقل، أيهما يتجنّب المشاكل؟ اختر الأفضل، ثم اجعله أفضل بعد.","Run both routes. Count the blocks in each.":"شغّل المسارين. عُدّ اللبنات في كل منهما.","Route A goes up and across in seven blocks. Can a repeat make it shorter?":"المسار A يصعد ويعبر في سبع لبنات. هل تستطيع لبنة كرّر أن تجعله أقصر؟","Put the first three moves of Route A inside one repeat.":"ضع الحركات الثلاث الأولى من المسار A داخل كرّر واحدة.","Two programs both work. The better one is usually the one that...":"برنامجان كلاهما يعمل. الأفضل عادةً هو الذي...","does the job with fewer steps or blocks":"يؤدّي المهمة بخطوات أو لبنات أقل","has the most blocks":"لديه أكبر عدد من اللبنات","was written first":"كُتب أولًا","Route A works but is long. Route B is short but bumps. Which is easier to fix?":"المسار A يعمل لكنه طويل. والمسار B قصير لكنه يصطدم. أيهما أسهل في الإصلاح؟","Route B turns one square too early. Fix its first repeat number.":"المسار B يستدير قبل مربّع واحد من موعده. أصلح عدد التكرار الأول فيه.","Change the first repeat of Route B from 3 to 4.":"غيّر أول كرّر في المسار B من 3 إلى 4.","A short program with one bug is often...":"البرنامج القصير الذي فيه خطأ واحد غالبًا ما يكون...","the better start: fix the bug and keep it short":"البداية الأفضل: أصلح الخطأ وأبقِه قصيرًا","useless":"عديم الفائدة","the same as a long one":"مثل البرنامج الطويل تمامًا","Route A is short. Why does it not count?":"المسار A قصير. لماذا لا يُحتسب؟","Route B works but spins on the spot near the end. Which turns cancel each other?":"المسار B يعمل لكنه يدور في مكانه قرب النهاية. أي استدارتين تلغي إحداهما الأخرى؟","Delete the turn left and turn right that come right after each other.":"احذف استدر يسارًا واستدر يمينًا اللتين تأتيان مباشرة إحداهما بعد الأخرى.","The shortest program drove into the water. Shortest is best only if...":"أقصر برنامج قاد إلى الماء. الأقصر هو الأفضل فقط إذا...","it still works":"كان ما زال يعمل","it has a loop":"كان فيه حلقة","it has no turns":"لم تكن فيه استدارات","Route B works with sixteen blocks. Route A has five but stops short.":"المسار B يعمل بست عشرة لبنة. والمسار A فيه خمس لكنه يتوقّف قبل الهدف.","Count the stairs. Route A repeats one stair too few.":"عُدّ الدرجات. المسار A يكرّر درجة أقل من اللازم.","Change Route A to repeat 4.":"غيّر المسار A إلى كرّر 4.","Compared to sixteen single blocks, a loop that does the same thing is...":"مقارنةً بست عشرة لبنة منفردة، الحلقة التي تفعل الشيء نفسه هي...","slower for Bolt":"أبطأ لبولت","less exact":"أقل دقة","Route A reaches the flag quickly. Why is the level not done?":"المسار A يصل إلى العلم بسرعة. لماذا لم يكتمل المستوى؟","Route B picks up both gems. Which part of it repeats?":"المسار B يلتقط الجوهرتين. أي جزء منه يتكرّر؟","Put the first gem trip of Route B (two moves and a pick up) inside a repeat.":"ضع أول رحلة إلى جوهرة في المسار B (حركتان والتقط) داخل كرّر.","Route A was fast but left the gems. Comparing routes means checking...":"المسار A كان سريعًا لكنه ترك الجواهر. مقارنة المسارات تعني التحقّق من...","that they do the whole job, then how well":"أنها تؤدّي المهمة كاملة، ثم كيف تؤدّيها","only the speed":"السرعة فقط","only the number of turns":"عدد الاستدارات فقط","A flowchart is a plan with shapes":"المخطط الانسيابي خطة بالأشكال","Boxes are actions. Diamonds are questions with a yes way and a no way. Build the flowchart first by putting its tiles in order. Then your blocks must follow it exactly: the level checks the program against the chart.":"المستطيلات أفعال. والمعيّنات أسئلة لها طريق نعم وطريق لا. ابنِ المخطط الانسيابي أولًا بترتيب بلاطاته. بعدها يجب أن تتبعه لبناتك بالضبط: المستوى يقارن البرنامج بالمخطط.","Follow the chart with your finger: what happens at the diamond?":"تتبّع المخطط بإصبعك: ماذا يحدث عند المعيّن؟","The chart says: until the goal, if path ahead then move, else turn right. Your blocks must say the same.":"المخطط يقول: حتى الهدف، إذا الطريق مفتوح فتحرّك، وإلا استدر يمينًا. يجب أن تقول لبناتك الشيء نفسه.","The diamond is an if / else inside repeat until goal. Move goes in the if part.":"المعيّن هو إذا / وإلا داخل كرّر حتى الهدف. تحرّك تذهب في جزء إذا.","In a flowchart, a diamond is...":"في المخطط الانسيابي، المعيّن هو...","a question with a yes way and a no way":"سؤال له طريق نعم وطريق لا","an action":"فعل","the end":"النهاية","Start":"البداية","Is Bolt on the goal? Yes: stop":"هل بولت على الهدف؟ نعم: توقّف","Is the path ahead clear?":"هل الطريق أمامه مفتوح؟","Yes: move forward":"نعم: تحرّك للأمام","No: turn right":"لا: استدر يمينًا","Back to the top":"عُد إلى الأعلى","Two diamonds this time. Which question comes first in the chart?":"معيّنان هذه المرة. أي سؤال يأتي أولًا في المخطط؟","First: if on a gem, pick up. Then: if path ahead move, else turn right.":"أولًا: إذا على جوهرة، التقط. ثم: إذا الطريق مفتوح تحرّك، وإلا استدر يمينًا.","The first diamond is an if on a gem block holding pick up.":"المعيّن الأول هو لبنة إذا على جوهرة وفيها التقط.","Two diamonds in a row mean...":"معيّنان متتاليان يعنيان...","two questions asked one after the other every time round":"سؤالين يُطرحان واحدًا بعد الآخر في كل دورة","one question asked twice":"سؤالًا واحدًا يُطرح مرتين","the chart is broken":"أن المخطط معطّل","Is there a gem here? Yes: pick it up":"هل هنا جوهرة؟ نعم: التقطها","The chart has a side branch that starts with When. Which block is that?":"في المخطط فرع جانبي يبدأ بـ «عندما». أي لبنة هي تلك؟","When Bolt bumps, turn left. The main loop just moves until the goal.":"عندما يصطدم بولت، استدر يسارًا. الحلقة الرئيسية تتحرّك فقط حتى الهدف.","The side branch is a when bump block: put turn left inside it.":"الفرع الجانبي هو لبنة عندما يصطدم بولت: ضع استدر يسارًا داخلها.","A When branch in the chart runs...":"فرع «عندما» في المخطط يعمل...","whenever its event happens, wherever the main loop is":"كلما وقع حدثه، أينما كانت الحلقة الرئيسية","only at the end":"في النهاية فقط","When Bolt bumps: turn left":"عندما يصطدم بولت: استدر يسارًا","Move forward":"تحرّك للأمام","Now the hallway is two squares longer":"الآن الممرّ أطول بمربّعين","A program that counts squares breaks when the hallway grows. Test 2 is the same level with a longer hallway. Follow the flowchart: drive until the wall, turn, drive until the goal. Then both tests pass.":"البرنامج الذي يعدّ المربّعات يتعطّل عندما يطول الممرّ. الاختبار 2 هو المستوى نفسه بممرّ أطول. اتبع المخطط الانسيابي: قُد حتى الجدار، استدر، قُد حتى الهدف. عندها ينجح الاختباران.","The old program passes test 1. Run test 2. What changed?":"البرنامج القديم ينجح في الاختبار 1. شغّل الاختبار 2. ما الذي تغيّر؟","Counting four moves only fits the short hallway. The chart says drive until the wall.":"عدّ أربع حركات يناسب الممرّ القصير فقط. المخطط يقول قُد حتى الجدار.","Replace repeat 4 with repeat until wall ahead.":"استبدل كرّر 4 بـ كرّر حتى جدار أمامي.","A program that passes test 1 and fails test 2...":"البرنامج الذي ينجح في الاختبار 1 ويفشل في الاختبار 2...","is not finished yet":"لم يكتمل بعد","is finished":"مكتمل","needs more moves":"يحتاج إلى مزيد من الحركات","Is there a wall ahead? No: move forward and ask again":"هل هناك جدار أمامه؟ لا: تحرّك للأمام واسأل من جديد","Yes: turn left":"نعم: استدر يسارًا","Is Bolt on the goal? No: move forward and ask again":"هل بولت على الهدف؟ لا: تحرّك للأمام واسأل من جديد","Yes: stop":"نعم: توقّف","Three tests: the corner and the gems move. Only a chart-shaped program passes all three.":"ثلاثة اختبارات: الزاوية والجواهر تتغيّر أماكنها. فقط البرنامج الذي على شكل المخطط ينجح فيها كلها.","Pick up if on a gem. Then: if path ahead move, else turn left.":"التقط إذا على جوهرة. ثم: إذا الطريق مفتوح تحرّك، وإلا استدر يسارًا.","The same program passed three different boards because...":"البرنامج نفسه نجح على ثلاث لوحات مختلفة لأنه...","it asked questions instead of counting":"طرح أسئلة بدلًا من العدّ","the boards were the same":"اللوحات كانت متشابهة","No: turn left":"لا: استدر يسارًا","Plan, build, test, improve":"خطّط، ابنِ، اختبر، حسّن","In the Level Maker you paint the board: pick a tile, tap a square. Check proves a level can be solved and tells you its par. Test with a friend hands the device over. Nothing is typed: a level code carries the whole board.":"في صانع المستويات ترسم اللوحة: اختر بلاطة، وانقر مربّعًا. تحقّق يثبت أن المستوى قابل للحل ويخبرك بحدّه الأدنى. واختبره مع صديق يسلّم الجهاز. لا شيء يُكتب: رمز المستوى يحمل اللوحة كلها.","Where is the goal? Which squares around it are walls?":"أين الهدف؟ أي المربّعات حوله جدران؟","Pick the floor tile and tap one wall next to the goal that touches the corridor.":"اختر بلاطة الأرضية وانقر جدارًا واحدًا بجانب الهدف يلامس الممرّ.","Tap the wall on the left of the goal, then press Check.":"انقر الجدار الذي على يسار الهدف، ثم اضغط تحقّق.","Check turns red and says no way to the goal. That means...":"تحقّق يصبح أحمر ويقول لا طريق إلى الهدف. هذا يعني أن...","no program could ever solve the level":"لا برنامج يمكنه حلّ المستوى أبدًا","the level is hard":"المستوى صعب","Bolt is tired":"بولت متعب","The goal is walled in. Open one wall so Bolt can reach it, then press Check.":"الهدف محاط بالجدران. افتح جدارًا واحدًا ليستطيع بولت الوصول إليه، ثم اضغط تحقّق.","Pick the floor tile and open a way from the corridor to the goal.":"اختر بلاطة الأرضية وافتح طريقًا من الممرّ إلى الهدف.","Open the two walls between the corridor and the goal, then press Check.":"افتح الجدارين بين الممرّ والهدف، ثم اضغط تحقّق.","The goal is walled in. Open walls so Bolt can reach it, then press Check.":"الهدف محاط بالجدران. افتح جدرانًا ليستطيع بولت الوصول إليه، ثم اضغط تحقّق.","Par is the fewest commands a perfect program needs. How do you make Bolt work harder?":"الحد الأدنى هو أقل عدد من الأوامر يحتاجه برنامج مثالي. كيف تجعل بولت يعمل بجهد أكبر؟","Move the goal to the far corner, or put walls in the straight way.":"انقل الهدف إلى الزاوية البعيدة، أو ضع جدرانًا في الطريق المستقيم.","Put the goal in the bottom corner and a wall in the middle, then press Check.":"ضع الهدف في الزاوية السفلية وجدارًا في المنتصف، ثم اضغط تحقّق.","Your tester said the level was too easy. A good next step is...":"قال من جرّب مستواك إنه سهل جدًا. خطوة تالية جيدة هي...","change the level using what they said, then test again":"أن تغيّر المستوى بحسب ما قاله، ثم تجرّبه مرة أخرى","tell them they played it wrong":"أن تقول له إنه لعب بطريقة خاطئة","start a new level and never test it":"أن تبدأ مستوى جديدًا ولا تجرّبه أبدًا","Too easy: par is 1. Move the goal or add walls until par is at least 6. Keep it solvable.":"سهل جدًا: الحد الأدنى 1. انقل الهدف أو أضف جدرانًا حتى يصبح الحد الأدنى 6 على الأقل. أبقِه قابلًا للحل.","Move the goal far away and put a wall across the straight way.":"انقل الهدف بعيدًا وضع جدارًا يقطع الطريق المستقيم.","Put the goal in the bottom corner and a long wall in the middle, then press Check.":"ضع الهدف في الزاوية السفلية وجدارًا طويلًا في المنتصف، ثم اضغط تحقّق.","Too easy: par is 1. Move the goal or add walls until par is at least 10. Keep it solvable.":"سهل جدًا: الحد الأدنى 1. انقل الهدف أو أضف جدرانًا حتى يصبح الحد الأدنى 10 على الأقل. أبقِه قابلًا للحل.","A door only opens for a key. Where must the key be?":"الباب لا يفتح إلا بمفتاح. أين يجب أن يكون المفتاح؟","Put the key before the door on the way, and a gem anywhere Bolt can reach.":"ضع المفتاح قبل الباب على الطريق، وجوهرة في أي مكان يستطيع بولت الوصول إليه.","Gem next to Bolt, key on the left side, door right before the goal. Then Check.":"جوهرة بجانب بولت، مفتاح على الجانب الأيسر، باب قبل الهدف مباشرة. ثم تحقّق.","A level with a door, no key and no gems is...":"مستوى فيه باب، بلا مفتاح ولا جواهر، هو...","unsolvable: Check will refuse it":"غير قابل للحل: تحقّق سيرفضه","harder":"أصعب","Make it a quest: add a gem, a key and a door on the way to the goal. Keep it solvable.":"اجعله مغامرة: أضف جوهرة ومفتاحًا وبابًا على الطريق إلى الهدف. أبقِه قابلًا للحل.","A remix keeps the based-on stamp and changes something real.":"الريمكس يُبقي ختم «مبني على» ويغيّر شيئًا حقيقيًا.","Add gems, a puddle or a wall: three squares or more. Then Check.":"أضف جواهر أو بركة أو جدارًا: ثلاثة مربّعات أو أكثر. ثم تحقّق.","Put two gems on the way and a puddle in the bottom row, then press Check.":"ضع جوهرتين على الطريق وبركة في الصف السفلي، ثم اضغط تحقّق.","The based-on stamp on a remixed level...":"ختم «مبني على» في المستوى المعاد مزجه...","credits the level it came from":"ينسب الفضل إلى المستوى الذي جاء منه","makes it harder":"يجعله أصعب","is the par":"هو الحد الأدنى","Remix: this level came from a code. Change at least three squares, keep it solvable, and keep the based-on stamp.":"ريمكس: هذا المستوى جاء من رمز. غيّر ثلاثة مربّعات على الأقل، أبقِه قابلًا للحل، وأبقِ ختم «مبني على».","Bump! A wall after step {n}. Bolt did exactly what the blocks said.":"بوم! جدار بعد الخطوة {n}. فعل بولت بالضبط ما قالته اللبنات.","The door is shut. What does it need before Bolt can go through?":"الباب مغلق. ماذا يحتاج قبل أن يستطيع بولت المرور؟","The door checks the box as Bolt steps in. Bolt reached the door before the box was filled, so it stayed shut. Fill the box first, then walk in.":"يفحص الباب الصندوق عندما يخطو بولت إلى الداخل. وصل بولت إلى الباب قبل أن يمتلئ الصندوق، فبقي مغلقًا. املأ الصندوق أولًا ثم ادخل.","Splash! Bolt drove into the water after step {n}.":"سبلاش! قاد بولت إلى الماء بعد الخطوة {n}.","Bolt reached down after step {n}, but there was nothing to pick up there.":"مدّ بولت يده بعد الخطوة {n}، لكن لم يكن هناك شيء لالتقاطه.","One gem is still out there.":"ما زالت هناك جوهرة واحدة في الخارج.","{n} gems are still out there.":{"zero":"ما زالت هناك {n} جواهر في الخارج.","one":"ما زالت هناك {n} جوهرة في الخارج.","two":"ما زالت هناك {n} جوهرتان في الخارج.","few":"ما زالت هناك {n} جواهر في الخارج.","many":"ما زالت هناك {n} جوهرة في الخارج.","other":"ما زالت هناك {n} جوهرة في الخارج."},"Bolt stopped, but not on the goal.":"توقّف بولت، لكن ليس على الهدف.","Bolt ran out of energy: the program goes on and on. Is a loop going round and round?":"نفدت طاقة بولت: البرنامج يستمر بلا نهاية. هل هناك حلقة تدور وتدور؟","Bolt ran out of energy: the loop never stopped. A sensor checks the square Bolt is standing on, so the answer only changes when Bolt moves to a new square.":"نفدت طاقة بولت: لم تتوقف الحلقة أبدًا. يفحص المستشعر المربع الذي يقف عليه بولت، لذا لا تتغير الإجابة إلا عندما ينتقل بولت إلى مربع جديد.","The blocks call each other too deeply.":"اللبنات تستدعي بعضها بعضًا بعمق كبير جدًا.","{name} is not a clear name. A partner could not tell what is in that box.":"{name} ليس اسمًا واضحًا. لن يعرف زميلك ما في ذلك الصندوق.","This level needs {block}. The learn card shows how.":"هذا المستوى يحتاج إلى {block}. بطاقة التعلّم تُريك الطريقة.","Split the route into named blocks first.":"قسّم المسار إلى لبنات مسمّاة أولًا.","A note chip does not match what its block does.":"بطاقة ملاحظة لا تطابق ما تفعله لبنتها.","Add a note chip to {name}: what does that block do?":"أضف بطاقة ملاحظة إلى {name}: ماذا تفعل تلك اللبنة؟","Keep the block {name} and its credit line: it says where the block came from.":"أبقِ اللبنة {name} وسطر مصدرها: فهو يذكر من أين جاءت اللبنة.","Remix means change something. {name} is still exactly the starter block.":"الريمكس يعني أن تغيّر شيئًا. {name} ما زالت اللبنة الجاهزة نفسها بالضبط.","The program does not follow the flowchart. Check each box and diamond against your blocks.":"البرنامج لا يتبع المخطط الانسيابي. قارن كل مستطيل ومعيّن بلبناتك.","A block is called that was never made.":"تم استدعاء لبنة لم تُصنع أبدًا.","Something in the program is not a block Bolt knows.":"شيء ما في البرنامج ليس لبنة يعرفها بولت.","Use the shared block {name}: call it from your program.":"استخدم اللبنة المشتركة {name}: استدعِها من برنامجك.","A when block only works on its own, at the top level. Inside another block it cannot listen for anything. Move it out.":"يعمل قالب «عندما» فقط بمفرده، في المستوى الأعلى. داخل قالب آخر لا يمكنه الاستماع إلى أي شيء. أخرجه إلى الخارج.","A My Block only works on its own, at the top level. Inside another block it cannot be made. Move it out.":"يعمل «قالبي» فقط بمفرده، في المستوى الأعلى. داخل قالب آخر لا يمكن إنشاؤه. أخرجه إلى الخارج."}} });
